"""Explain the verified handoff audit and retain external-validation limits."""
from pathlib import Path
from itertools import combinations
import json,math
import numpy as np
from run_population_study import ROOT,save,sha
from verify_population_study import rational


def read(p):return json.loads(p.read_text())


def main():
    study=ROOT/'results/game2-handoff-integration';r=read(study/'results.json');a=read(study/'acceptance.json');assert a['passed'];out=ROOT/'results/game2-handoff-review'
    if out.exists():raise SystemExit('Review exists; preserve it.')
    out.mkdir();public=read(ROOT/'data/parry-handoff/public-scores.json');observed=np.sort(np.array(public['scores']));total=sum(v['own_unique_actions']for v in r['cdf'].values()if v['definition']['kind']=='arena');precision={}
    for key,v in r['cdf'].items():
        if v['definition']['kind']!='arena':continue
        with np.load(study/'cdf'/(key+'.npz'))as f:h=f['rank_sum4']/(4*int(f['size']));weights=f['own_weights'].astype(float);N=int(f['size'])
        weights/=weights.sum();order=np.argsort(h);h=h[order];weights=weights[order];cw=np.cumsum(weights);eps=9*math.sqrt(math.log(2*total/.05)/(2*N));knots=np.unique(np.r_[observed,h-eps,h+eps]);points=np.r_[knots,np.nextafter(knots,-np.inf)]
        def cdf(t):
            ix=np.searchsorted(h,t,side='right');return np.where(ix>0,cw[np.maximum(ix-1,0)],0)
        F=np.searchsorted(observed,points,side='right')/len(observed);lo=cdf(points-eps-1e-12);hi=cdf(points+eps+1e-12);gap=float(np.maximum.reduce([lo-F,F-hi,np.zeros(len(points))]).max());assert 0<=gap<=v['metrics']['maximum_cdf_gap']+1e-12
        precision[key]={'simultaneous_score_mean_error_bound':eps,'necessary_cdf_gap_after_mc_allowance':gap}
    save(out/'arena-cdf-precision.json',{'alpha':.05,'models':precision,'scope':'Allows our opponent-sampling score error only; not public reshuffle noise, a confidence region for hidden populations, or identification'})
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(9,5));xx=np.linspace(0,9,1001);ax.plot(xx,np.searchsorted(observed,xx,side='right')/len(observed),color='black',lw=2.4,label='Published score CDF')
    chosen={'arena__replicator__fifth__balanced__tail':'Replicator arena, tail','arena__prior_replacement__fifth__balanced__tail':'Prior-replacement arena, tail','core__edge__p0.1':'Sparse broad model, 10% exact all-in','core__counter_aware__p0.1':'Counter-aware broad model, 10% exact all-in'}
    for key,label in chosen.items():
        with np.load(study/'cdf'/(key+'.npz'))as f:h=f['rank_sum4']/(4*int(f['size']));w=f['own_weights'].astype(float)
        w/=w.sum();order=np.argsort(h);h=h[order];w=w[order];cw=np.cumsum(w);ix=np.searchsorted(h,xx,side='right');yy=np.where(ix>0,cw[np.maximum(ix-1,0)],0);ax.plot(xx,yy,label=label,lw=1.5)
    ax.set(xlabel='Incumbent mean ranking payout',ylabel='Cumulative population mass',xlim=(0,9),ylim=(0,1),title='Public-score model check: correct scoring does not validate opponent laws');ax.grid(alpha=.2);ax.legend(fontsize=8);fig.tight_layout();fig.savefig(out/'public-cdf-model-check.png',dpi=170);plt.close(fig)
    rows=list(combinations(range(5),2))+list(combinations(range(5),3));matrix=[];P=r['target_scores'][r['named']['parry_selected']];O=r['target_scores'][r['named']['our_selected']]
    for active in rows:
        line=[]
        for scout in r['configuration']['scouts']:
            keys=['target'+''.join(str(i+1)for i in active)+'__s'+str(scout)+'__'+mode for mode in r['configuration']['target_weightings']];line.append(sum(float(rational(P[k])-rational(O[k]))for k in keys)/len(keys))
        matrix.append(line)
    fig,ax=plt.subplots(figsize=(9,8));im=ax.imshow(matrix,cmap='RdBu_r',vmin=-9,vmax=9,aspect='auto');ax.set_yticks(range(len(rows)),['+'.join(str(i+1)for i in row)for row in rows]);ax.set_xticks(range(7),r['configuration']['scouts']);ax.set(xlabel='Inactive-castle scout bid',ylabel='Opponents concentrated on these castles',title='Parry minus our current selection: structural stresses\nEach cell averages three explicit split-weighting proxies')
    fig.colorbar(im,ax=ax,label='Ranking-payout difference; positive favors Parry');fig.tight_layout();fig.savefig(out/'target-sensitivity.png',dpi=170);plt.close(fig)
    winsP=sum(rational(P[k])>rational(O[k])for k in P);winsO=sum(rational(P[k])<rational(O[k])for k in P);ties=len(P)-winsP-winsO
    summary={'source_results_sha256':sha(study/'results.json'),'source_acceptance_sha256':sha(study/'acceptance.json'),'current_recommendation_record_unchanged':True,'recommendation_status':'Version 1 retained as a recorded conditional choice; external population validation and cross-arena replay pending',
        'target_scenario_comparisons':{'parry_higher':winsP,'our_higher':winsO,'ties':ties},'nominal_cdf_passes':{kind:sum(v['metrics']['passes_nominal_screen']for v in r['cdf'].values()if v['definition']['kind']==kind)for kind in ['arena','core']},
        'missing_artifacts':['results/field_fit_validated.json','results/fit_catalog.npz','results/fit_catalog_weights.npz','field_fit.py','arena.py','lookup.cpp','results/memory_equilibrium_best.json (strategic checkpoint comparison)'],
        'verified_theory':{'symmetric_equilibrium_allin_atom_floor':r['theory']['necessary_symmetric_equilibrium_allin_mass_lower_bound'],'critical_response_proof':'Within-cell lowering of non-slack coordinates preserves their outcomes; moving surplus to the slack coordinate cannot reduce rank payout'},
        'scope':'Independent audit and development expansion; no reproduction of Parry fitted fields and no new final allocation selected'}
    save(out/'results.json',summary)
    fmt=lambda x:f'{float(rational(x)):.3f}'
    lines=['**Parry handoff: what checks out, what it changes, and what we added**','','The handoff is technically useful. Its explicit examples and main mathematical deductions check out. It adds two important elements to our work: public-score compatibility checks and separate treatment of every castle pair and triple. It also reports a substantially larger own-action search. Its numerical population fits and recommendation cannot yet be reproduced because the project code, sampled catalog, and fitted weights were not supplied.','','The key disagreement is now clearer. Both projects optimize official average 9/4/2/0 placement payout. Parry then maximizes the lowest payout across seventeen score-compatible hypothetical fields. Our final rule minimizes the largest shortfall across three coverage blocks, one of which deliberately contains severe counterstyles. Different uncertainty sets and decision rules can select different vectors without a scoring error.','','**A material gap in our earlier validation**','','The new fetch from the [public leaderboard dataset](https://pokerbot.sequoiacap.com/castle_challenge/data/leaderboard.json) has generation time '+public['generated_at']+'. It still contains 1,649 Game 2 scores, with mean 3.750708, minimum 0.546 and maximum 6.497. Its reported percentiles match the handoff after rounding. This verifies the summary statistics against a new fetch, not byte identity with Parry\'s unavailable older snapshot. The delivered dataset retains scores only, excluding names, schools and IDs.','','Our previous pipeline did not compare its modeled incumbent-score CDFs with this public evidence. I added that diagnostic to all sixteen whole-run/tail arena laws and sixteen balanced broad-law variants. None passed the nominal 0.085 maximum-CDF-gap, 0.035 mean-gap and 0.015 upper-tail thresholds under our declared metrics. Our mean-gap grid and own-action sampling are explicit independent choices; this is not a reproduction of Parry\'s screen implementation. The other non-balanced broad variants have not all received this CDF check.','','For the arena laws, the raw maximum gaps range from about 0.179 to 0.441. Even allowing a simultaneous 95% bound of about 0.087 on our own estimated action scores, their necessary CDF gaps remain about 0.147 to 0.406, above 0.085. That allowance covers our score-estimation Monte Carlo error, not noise in the published reshuffle averages or uncertainty in the actual cohort. The broad-law checks also have own-action sampling noise, so their nominal failures are not formal statistical rejections.','','This does not make our arithmetic wrong. It means that successful performance against these training and stress populations is insufficient evidence that they describe applicants. They remain useful stress models. A calibrated plausible-population block should be evaluated separately before treating the practical choice as settled. The public distribution is much more dispersed than the near-equilibrium-looking replicator populations.','','![Public CDF comparison](blotto-lab/results/game2-handoff-review/public-cdf-model-check.png)','','A population sampled against itself has mean 3.75 regardless of its strategic quality. Matching that mean was never enough. Matching more of the distribution is a better diagnostic, but still cannot identify hidden allocations.','','**The identification warning is correct**','','For five-grid bids, transforming each incumbent coordinate by T(y)=4y/5+4 preserves legality, all incumbent comparisons, all ties, and every incumbent score. A new fixed entry need not retain its score. The handoff\'s entrant (30,30,0,20,20) scores 3.75 against three copies of (0,0,0,50,50), but zero against three copies of (4,4,4,44,44). I verified that exact example and 200 additional transformed groups. This construction applies to the stated five-grid domain, not automatically to every integer catalog.','','Consequently, the seventeen retained fields are hypotheses inside Parry\'s forty-family catalog. Their compatibility tolerances do not form a posterior or a confidence region for hidden bids. A new candidate may legitimately score above the existing leaderboard maximum. The tail check concerns a model\'s generated incumbent population, not a cap on an entrant\'s payoff. Repeated published scores also do not identify duplicate allocations.','','**The mathematical contributions we can use**','','The exact heterogeneous example explaining denial of castle 2 is correct: against the three explicitly defined opponents, 36/64 earns nine payout points, 39/61 earns 6.5, and the scout entry earns four. All twelve explicit homogeneous-table outcomes also match our scorer. These verify the listed cases, not every unspecified proportional template or every numerical simulation table.','','The identical-marginal counterexample is correct: the castle-3 all-in earns 4.25 raw castle points against either population but mean ranking payouts of 5.625 and 7.125. This reinforces why complete joint allocations are necessary. The no-pure-symmetric-equilibrium argument, conditional all-in-five bounds, and collision approximation are also sound under the stated rules.','','A particularly useful new deduction concerns A=(0,0,0,0,100). If its opponent share is p, the lower bound is L(p)=4-9p+12p^2-(13/4)p^3. In a symmetric Nash equilibrium no deviation can exceed 3.75, so p must be at least (35-sqrt(1173))/26, approximately 2.8881%. A therefore has positive support and earns exactly 3.75 against every true symmetric equilibrium. This is a special equilibrium fact, not a guarantee of 3.75 against human populations or approximate numerical checkpoints. It does not turn pure A into a Nash equilibrium.','','I implemented the finite-support critical-level reduction. Four coordinates can be restricted to zero, observed bids, and one above observed bids, with the remaining budget assigned to the fifth. Lowering a coordinate within its comparison cell leaves every group outcome there unchanged; moving the surplus to the remaining coordinate cannot worsen placement. This supplies a global response value for a fixed finite iid support, although the best representative need not be the globally lexicographically first optimum. Dense supports can still make the search expensive. Exhaustive reduced-game checks validate the new implementation.','','The new exact oracle finds (0,27,1,65,7) against an equal mixture of our selected vector and Parry\'s vector, with payout nine. More strongly, it wins castles 4 and 5 outright against every group made solely of those two vectors, totaling at least nine castle points. Thus it earns nine against every such group. This is a restricted-pool result and is not a proposed universal submission. It is now included in the development pool.','','**Concrete pool improvements completed**','','The expanded pool contains 498 unique candidates: all previous 191, every integer C2/C4 split, every integer C3/C4 split, the handoff\'s fixed contenders and mixture branches, small transfers around our selected vector and its alternative, unrestricted controls, and exactly checked small-support responses. This directly addresses gaps such as the absence of Parry\'s exact vector and nearby alternatives around our previous selection.','','The new stress bank has 420 scenarios: all ten pairs and ten triples, seven inactive scout levels (0,1,3,5,6,8,10), and three explicit weightings over every feasible active integer split with each active bid at least eight. The weightings are uniform or kernels around equal/value-centered splits. These are independent transparent proxies, not Parry\'s exact basket weights, which remain unavailable. Each scenario has 4,096 full joint opponent trios. These are concentrated stresses, not applicant forecasts.','','| Named entry | Lowest scenario mean | Equal-scenario mean | Highest scenario mean |','| --- | ---: | ---: | ---: |']
    for name in ['our_selected','parry_selected','parry_34','parry_scout','our_lowest_model','all_in_five','parry_earlier']:
        cid=r['named'][name];values=list(r['target_scores'][cid].values());v=[rational(x)for x in values];lines.append(f"| {tuple(r['pool'][cid]['allocation'])} | {float(min(v)):.3f} | {float(sum(v)/len(v)):.3f} | {float(max(v)):.3f} |")
    lines+=['',f"Our recorded selection scores higher in {winsO} of the 420 scenarios, Parry\'s in {winsP}, with {ties} exact sampled-score ties. Those counts are coverage statistics, not probabilities that either will be better against applicants. They also depend on the proxy weights, so they do not replicate his results.",'','All-in five has a strong minimum here partly because every pair/triple law requires at least eight troops in each active castle. Exact 100-five entries are excluded, so it always faces a no-copy group. Likewise, the high equal-scenario mean of Parry\'s earlier 69-five hypothesis does not revive it as the recommendation. These construction effects are precisely why we should not average concentrated target scenarios into an applicant forecast.','','![Target/scout comparison](blotto-lab/results/game2-handoff-review/target-sensitivity.png)','','**What remains reported, rather than independently verified**','','The supplied text does not include the seventeen fitted population weights, catalog arrays, original public snapshot, 23,443 candidate archive, native scorer, full-space screen cache, split-audit arrays, or seventy-action equilibrium checkpoint. I therefore cannot certify its exhaustive search, fifteen passing tests, 5.365 minimum, paired split standard errors, or 4.025352 global deviation value. The theoretical explanations and scope qualifications are credible, but those numerical claims still require replay. His reported all-action screen is broader than our 4,612-vector development screen; a float16 shortlist followed by fresh audits still does not certify the hidden-field optimum.','','The approximate equilibrium checkpoint should be added as an opponent when supplied. A remaining best-response gain of 0.275352 is not zero, so it does not establish equilibrium. Its globally checked deviation claim also has a different scope from our frozen-field response witnesses. The allocation-mixture warning is correct: a policy\'s expected score before one draw cannot be attached to the one row eventually submitted.','','The cited multiplayer Blotto and General Lotto research exists and the stated scope cautions are appropriate. Continuous battlefield payoffs, budgets constrained only in expectation, and round-robin allocation contests do not solve Sequoia\'s integer four-way placement game. The 2026 resource-allocation preprint was also independently located. [Multiplayer Blotto](https://arxiv.org/abs/2002.05240), [Multiplayer General Lotto](https://researchportal.bath.ac.uk/en/publications/multiplayer-general-lotto-game/), [Resource Allocation Tournament](https://arxiv.org/abs/2610.31418).','','**Decision and the next input**','','Keep our version-1 record intact, but treat the practical choice as provisional pending the external population comparison. This handoff does not justify automatically replacing it with 36/64. It does justify revisiting the population model and uncertainty rule before claiming either final choice is settled. The public-score check is material new evidence.','','The next useful input is Parry\'s project archive, especially results/field_fit_validated.json, results/fit_catalog.npz, results/fit_catalog_weights.npz, and field_fit.py, arena.py and lookup.cpp. His saved current decision, final audit and split audit support the numerical replay. The strategic checkpoint and critical oracle are useful for adding his strongest learned opponents.','','With those files, we can reproduce the retained fields, run all new candidates against his actual populations, preserve both calibrated-field and stress results separately, and freeze a joint selection rule before fresh validation. We should challenge both candidates symmetrically and avoid choosing population weights merely to make either previous recommendation win.','','All 105 tests passed. The independent audit checked the complete new score sums, 22,364,160 named candidate/group cells with the foundation scorer, 6,693,120 all-pool target spot cells, and all 32 CDF diagnostics, plus theory fixtures and source integrity. Original Game 1 and Game 2 records remain unchanged. The [audit record](blotto-lab/results/game2-handoff-integration/acceptance.json), [expanded pool](blotto-lab/results/game2-handoff-integration/pool-freeze.json), [CDF table](blotto-lab/results/game2-handoff-integration/public-cdf-diagnostics.csv), [target summaries](blotto-lab/results/game2-handoff-integration/named-target-summary.csv), and [sanitized public scores](blotto-lab/data/parry-handoff/public-scores.json) retain the evidence. No application has been submitted.','']
    report=ROOT.parent/'25-parry-handoff-audit-and-integration.md';text='\n'.join(lines);assert '\u2014'not in text and text.rstrip().endswith('.');report.write_text(text)
    save(out/'manifest.json',{'source_sha256':sha(Path(__file__)),'inputs':{str(p.relative_to(ROOT)):sha(p)for p in [study/'results.json',study/'acceptance.json',ROOT/'data/parry-handoff/public-scores.json']},'artifacts':{p.name:sha(p)for p in out.iterdir()if p.is_file()and p.name!='manifest.json'},'report_sha256':sha(report)})
    print('Handoff review and development additions saved. Original selections remain unchanged; external replay pending.')


if __name__=='__main__':main()
